SELECT w.w_warehouse_name, cd.cd_gender, COUNT(DISTINCT ss.ss_ticket_number) AS tickets_sold, COUNT(DISTINCT cr.cr_order_number) AS returns_processed, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(cr.cr_return_amount) AS total_returns, SUM(ss.ss_ext_sales_price) - SUM(cr.cr_return_amount) AS net_revenue, RANK() OVER (ORDER BY SUM(ss.ss_ext_sales_price) DESC) AS sales_rank FROM warehouse w LEFT JOIN catalog_returns cr ON cr.cr_warehouse_sk = w.w_warehouse_sk LEFT JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk LEFT JOIN store_sales ss ON ss.ss_cdemo_sk = cd.cd_demo_sk WHERE w.w_state = 'CA' GROUP BY w.w_warehouse_name, cd.cd_gender HAVING SUM(ss.ss_ext_sales_price) > 0 ORDER BY net_revenue DESC LIMIT 20
